CREATE TABLE "public"."agendamentos" (
  "id"          bigint                 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "cliente_id"  bigint                 NOT NULL,
  "barbeiro_id" bigint                 NOT NULL,
  "servico_id"  bigint                 NOT NULL,
  "data"        date                   NOT NULL,
  "horario"     time without time zone NOT NULL,
  "confirmado"  boolean                DEFAULT false,
  "status"      text                   NOT NULL DEFAULT 'pendente'::text,
  "fim_horario" time without time zone,
  CONSTRAINT "agendamentos_pkey" PRIMARY KEY (id),
  CONSTRAINT "ck_agend_fim" CHECK (((fim_horario IS NOT NULL) AND (fim_horario > horario))),
  CONSTRAINT "ck_agend_status" CHECK ((status = ANY (ARRAY['pendente'::text, 'confirmado'::text, 'concluido'::text, 'cancelado'::text]))),
  CONSTRAINT "ex_agend_sem_sobreposicao" EXCLUDE USING gist (barbeiro_id WITH =, tsrange((DATA + horario), (DATA + fim_horario), '[)'::text) WITH &&)
    WHERE ((status <> 'cancelado'::text)),
  CONSTRAINT "agendamentos_barbeiro_id_fkey" FOREIGN KEY (barbeiro_id) REFERENCES public.barbeiros(id),
  CONSTRAINT "agendamentos_cliente_id_fkey" FOREIGN KEY (cliente_id) REFERENCES public.clientes(id),
  CONSTRAINT "agendamentos_servico_id_fkey" FOREIGN KEY (servico_id) REFERENCES public.servicos(id)
);

ALTER TABLE "public"."agendamentos"
  ENABLE ROW LEVEL SECURITY;

CREATE INDEX ix_agend_barbeiro_data ON public.agendamentos USING btree (barbeiro_id, DATA) INCLUDE (horario, fim_horario, status);

CREATE INDEX ix_agend_cliente ON public.agendamentos USING btree (cliente_id);

CREATE INDEX ix_agend_pendentes ON public.agendamentos USING btree (DATA)
  WHERE (status = 'pendente'::text);

CREATE INDEX ix_agend_servico ON public.agendamentos USING btree (servico_id);

CREATE TRIGGER trg_agend_valida
  BEFORE INSERT OR UPDATE OF barbeiro_id, servico_id, DATA, horario, status ON public.agendamentos
  FOR EACH ROW
  EXECUTE FUNCTION public.trg_fn_valida_agendamento();

CREATE POLICY "cliente_cria_proprio_agendamento" ON "public"."agendamentos"
  FOR INSERT
  TO "authenticated"
  WITH CHECK (((status = 'pendente'::text) AND (EXISTS ( SELECT 1
   FROM public.clientes c
  WHERE ((c.id = agendamentos.cliente_id) AND (c.auth_user_id = auth.uid()))))));

CREATE POLICY "cliente_le_proprios_agendamentos" ON "public"."agendamentos"
  FOR SELECT
  TO "authenticated"
  USING ((EXISTS ( SELECT 1
   FROM public.clientes c
  WHERE ((c.id = agendamentos.cliente_id) AND (c.auth_user_id = auth.uid())))));

REVOKE ALL ON SEQUENCE "public"."agendamentos_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."agendamentos_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."agendamentos_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."agendamentos_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."agendamentos_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."agendamentos_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."agendamentos_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."agendamentos_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."agendamentos" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."agendamentos" TO "service_role";

REVOKE ALL ON TABLE "public"."agendamentos" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."agendamentos" TO "postgres";
